F=np.load('feats.npz'); y=F['y']
def stdz(X,tr): mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6; return (X-mu)/sd
def mkfolds(seed):
    rng=np.random.RandomState(seed); f2=np.zeros(len(y),int)
    for c in range(8):
        idx=np.where(y==c)[0]; rng.shuffle(idx); f2[idx]=np.arange(len(idx))%5
    return f2
FS=[mkfolds(s) for s in [0,7,11]]
def rcvZ(build,lams,kern=None):
    out=np.zeros(len(lams))
    for fo in FS:
        for f in range(5):
            tr=fo!=f; te=~tr
            Z=build(tr); Z=Z-Z[tr].mean(0)
            if kern is None: K=Z@Z[tr].T
            else:
                sq=(Z**2).sum(1); D=sq[:,None]+sq[tr][None,:]-2*Z@Z[tr].T; K=np.exp(-kern*D/Z.shape[1])
            Y=np.eye(8)[y[tr]]-1/8
            ev,U=np.linalg.eigh(K[tr]); UtY=U.T@Y
            for i,l in enumerate(lams):
                a=U@(UtY/(ev+l)[:,None]); out[i]+=(np.argmax(K[te]@a,1)==y[te]).sum()
    return np.round(out/(len(FS)*len(y)),4)
print('C9M9', rcvZ(lambda tr: np.concatenate([stdz(F['C9'],tr),stdz(F['M9'],tr)],1),[300,500,800]))
for extra in ['M0','M2','M4']:
    print('C9M9+'+extra, rcvZ(lambda tr: np.concatenate([stdz(F['C9'],tr),stdz(F['M9'],tr),stdz(F[extra],tr)],1),[300,500,800,1200]))
for g in [0.1,0.3]:
    print('rbf C9M9 g',g, rcvZ(lambda tr: np.concatenate([stdz(F['C9'],tr),stdz(F['M9'],tr)],1),[0.003,0.01,0.03,0.1],kern=g))
